 for entity in ('pitcher_id','batter_id'):
  for context in contexts:
   cell=hk.groupby([entity,context],observed=True).rel.agg(['sum','size']);own=hk.groupby(entity,observed=True).rel.agg(['sum','size']);cell=cell.join(own,rsuffix='_entity');cell['effect']=cell['sum']/cell['size']-cell['sum_entity']/cell['size_entity'];idx=pd.MultiIndex.from_arrays([rk[entity],rk[context]]);effect=np.nan_to_num(idx.map(cell.effect).to_numpy(float));seen=np.nan_to_num(idx.map(cell['size']).to_numpy(float))
   for k in shrinkages:out[f'state_{entity}_{context}_k{int(k)}']=effect*seen/(seen+k)
